    [GrasshopperCollection("Bench", "Math")]
    public interface IBenchMath : IBettaCollection
    {
        [GrasshopperMethod("Remap", "Remaps a number from a source range to a target range")]
        double Remap(
            [GrasshopperParameter("Value")] double value,
            [GrasshopperParameter("Source Min", DefaultValue = 0.0)] double sourceMin,
            [GrasshopperParameter("Source Max", DefaultValue = 1.0)] double sourceMax,
            [GrasshopperParameter("Target Min", DefaultValue = 0.0)] double targetMin,
            [GrasshopperParameter("Target Max", DefaultValue = 1.0)] double targetMax);

        [GrasshopperMethod("Clamp", "Limits a number to a range")]
        double Clamp(
            [GrasshopperParameter("Value")] double value,
            [GrasshopperParameter("Min", DefaultValue = 0.0)] double min,
            [GrasshopperParameter("Max", DefaultValue = 1.0)] double max);

        [GrasshopperMethod("Lerp", "Linearly interpolates between two numbers")]
        double Lerp(
            [GrasshopperParameter("A", DefaultValue = 0.0)] double a,
            [GrasshopperParameter("B", DefaultValue = 1.0)] double b,
            [GrasshopperParameter("T", DefaultValue = 0.5)] double t);
    }

    public class BenchMath : IBenchMath
    {
        public double Remap(double value, double sourceMin, double sourceMax, double targetMin, double targetMax)
        {
            if (sourceMax == sourceMin) throw new System.ArgumentException("Source range must not be empty.");
            return targetMin + (value - sourceMin) / (sourceMax - sourceMin) * (targetMax - targetMin);
        }

        public double Clamp(double value, double min, double max)
        {
            if (min > max) (min, max) = (max, min);
            return System.Math.Min(System.Math.Max(value, min), max);
        }

        public double Lerp(double a, double b, double t) => a + (b - a) * t;
    }

    [GrasshopperCollection("Bench", "Geometry")]
    public interface IBenchGeometry : IBettaCollection
    {
        [GrasshopperMethod("Divide Curve Stats", "Divides a curve into equal-length segments")]
        (System.Collections.Generic.List<Rhino.Geometry.Point3d> Points, double Length) DivideCurveStats(
            [GrasshopperParameter("Curve")] Rhino.Geometry.Curve curve,
            [GrasshopperParameter("Count", DefaultValue = 10)] int count);
    }

    public class BenchGeometry : IBenchGeometry
    {
        public (System.Collections.Generic.List<Rhino.Geometry.Point3d> Points, double Length) DivideCurveStats(
            Rhino.Geometry.Curve curve, int count)
        {
            if (curve == null) throw new System.ArgumentNullException(nameof(curve));
            if (count < 1) throw new System.ArgumentException("Count must be at least 1.");
            var points = new System.Collections.Generic.List<Rhino.Geometry.Point3d>();
            var parameters = curve.DivideByCount(count, true);
            if (parameters != null)
                foreach (var t in parameters) points.Add(curve.PointAt(t));
            return (points, curve.GetLength());
        }
    }

    [GrasshopperCollection("Bench", "Data")]
    public interface IBenchData : IBettaCollection
    {
        [GrasshopperMethod("Async Stats", "Mean and standard deviation of a list of numbers, computed asynchronously")]
        System.Threading.Tasks.Task<(double Mean, double StdDev)> AsyncStats(
            [GrasshopperParameter("Values")] System.Collections.Generic.List<double> values,
            System.Threading.CancellationToken cancellationToken);
    }

    public class BenchData : IBenchData
    {
        public System.Threading.Tasks.Task<(double Mean, double StdDev)> AsyncStats(
            System.Collections.Generic.List<double> values, System.Threading.CancellationToken cancellationToken)
        {
            return System.Threading.Tasks.Task.Run(() =>
            {
                if (values == null || values.Count == 0) return (0.0, 0.0);
                double sum = 0;
                foreach (var v in values) { cancellationToken.ThrowIfCancellationRequested(); sum += v; }
                double mean = sum / values.Count;
                double sq = 0;
                foreach (var v in values) { cancellationToken.ThrowIfCancellationRequested(); sq += (v - mean) * (v - mean); }
                return (mean, System.Math.Sqrt(sq / values.Count));
            }, cancellationToken);
        }
    }
'''
